/**
 * ===================================================================
 * 化学基礎：学習フローチャート（ロジックツリー）のデータ
 * ===================================================================
 *
 * このファイルにあるのは、解説画面で出てくる「思考の型」の図
 * （InteractiveTree に渡す木構造）だけ。★問題は1問も入っていない。★
 *
 * -------------------------------------------------------------------
 * ■ なぜ chemistryData.ts から分けたのか
 * -------------------------------------------------------------------
 * 元は chemistryData.ts の中に、問題データとこの図データが同居していた。
 * その結果 chemistryData.ts は 12,827行・801KB という大きさになり、
 *
 *   ・問題を1問足したいだけなのに、目的の場所を探すのに時間がかかる
 *   ・図を直したいだけなのに、問題データの中を通り抜けないと辿り着けない
 *
 * という状態だった。図データは「問題を増やす作業」では触らないので、
 * 先に切り離しておけば、問題側のファイルがそのぶん小さくなる。
 *
 * 中身は移動しただけで、1文字も変えていない。
 * 移動の前後で chemistryData.ts の全 export を JSON 化して
 * 突き合わせ、完全に同一であることを確認している。
 *
 * -------------------------------------------------------------------
 * ■ 呼び出し側から見た変化
 * -------------------------------------------------------------------
 * chemistryData.ts が同じ名前で再公開（re-export）しているので、
 *
 *     import { substanceTreeData } from '../data/chemistryData';
 *
 * という既存の書き方はそのまま動く。
 * 新しく書くときは、このファイルから直接 import したほうが
 * 「図だけが欲しい」ことがはっきりするので望ましい。
 *
 * -------------------------------------------------------------------
 * ■ このファイルは何も import しない（葉）
 * -------------------------------------------------------------------
 * 図データはただの定数なので、他のファイルを一切参照しない。
 * こうしておけば、どこから読み込んでも循環参照にならない。
 */

