          "explanation": "<u>物質の三態</u>＝同じ物質で、温度などの条件を変化させた<u>固体・液体・気体</u>の3つの状態。\n\n⏬【三態の比較表】\n\n|  | 固体 | 液体 | 気体 |\n| --- | --- | --- | --- |\n| 粒子間距離 | 小・引力大 | やや小・引力あり | 非常に大・引力ほぼなし |\n| 熱運動 | 小（その場で振動） | 大（自由に動く） | 非常に大（自由に飛ぶ） |\n| 形 | 一定 | 容器に応じ変化 | 容器に応じ変化 |\n| 体積 | 一定 | ほぼ一定 | 温度・圧力で大きく変化 |"
