          "explanation": "|  | 物理変化 | 化学変化 |\n| --- | --- | --- |\n| 定義 | 物質そのものは変わらず、状態のみが変わる | 原子の組み合わせが変わり、別の物質になる |\n| 例 | 水の蒸発、氷が溶ける、鉄を叩いて薄くする | 木の燃焼、鉄が錆びる、水の電気分解 |\n| 元に戻る？ | 基本、条件を戻せば戻る | 基本、元には戻らない |\n\n💡 <u>状態変化はすべて物理変化</u>！（水⇔氷⇔水蒸気は同じH₂O）"
